async def __aexit__(self, exc_type, exc, tb) -> None:
    try:
        if self._sb is not None:
            await self._sb.kill()
    except Exception as e:
        logger.warning("[agent.sandbox] kill %s failed: %s", self.sandbox_id[:8], e)
